-- Generated by scripts/gen-seed.js from src/data/seed-ideas.json. Do not edit by hand.

insert into public.ideas (id, mode, name, blurb, mood, cost, minutes, details, ingredients, steps)
overriding system value
values
  (1, 'cook', 'Creamy tomato pasta', 'Pantry pasta that tastes like a hug', 'comfy', 1, 20, 'Penne, canned tomatoes, garlic, a splash of cream and lots of parmesan.', '[{"qty":"12 oz","name":"penne"},{"qty":"1 can (14 oz)","name":"crushed tomatoes"},{"qty":"3 cloves","name":"garlic"},{"qty":"1/2 cup","name":"heavy cream"},{"qty":"1/2 cup","name":"grated parmesan"},{"qty":"2 tbsp","name":"olive oil"},{"qty":"1 pinch","name":"red pepper flakes"}]'::jsonb, '["Boil the penne in well-salted water until just tender. Save a cup of the pasta water.","While it cooks, warm the olive oil and garlic in a big pan for 1 minute.","Add the tomatoes and pepper flakes and simmer for 8 minutes.","Stir in the cream and parmesan.","Toss in the pasta with a splash of pasta water until glossy. Season and serve."]'::jsonb),
  (2, 'cook', 'Sheet-pan fajitas', 'One pan, zero fuss, big sizzle', 'spicy', 1, 25, 'Chicken, peppers and onions roasted hot with chili and cumin. Wrap in warm tortillas.', '[{"qty":"1 lb","name":"chicken breast"},{"qty":"2","name":"bell peppers"},{"qty":"1","name":"onion"},{"qty":"2 tbsp","name":"olive oil"},{"qty":"2 tsp","name":"chili powder"},{"qty":"1 tsp","name":"ground cumin"},{"qty":"8 small","name":"flour tortillas"},{"qty":"1","name":"lime"},{"qty":"","name":"sour cream, to serve"}]'::jsonb, '["Heat the oven to 425°F (220°C).","Slice the chicken, peppers and onion into strips.","Toss everything on a sheet pan with the oil, chili powder, cumin and a big pinch of salt.","Roast for 18 to 20 minutes, until the chicken is cooked and the edges char.","Warm the tortillas, squeeze lime over the pan, and wrap it up with sour cream."]'::jsonb),
  (3, 'cook', 'Teriyaki salmon bowls', 'Glossy salmon over rice', 'fresh', 2, 25, 'Pan-seared salmon, quick teriyaki glaze, rice, cucumber and sesame.', '[{"qty":"2","name":"salmon fillets"},{"qty":"1 cup","name":"white rice"},{"qty":"3 tbsp","name":"soy sauce"},{"qty":"2 tbsp","name":"honey"},{"qty":"1 tsp","name":"grated ginger"},{"qty":"1","name":"cucumber"},{"qty":"1 tbsp","name":"sesame seeds"},{"qty":"2","name":"scallions"}]'::jsonb, '["Cook the rice.","Stir together the soy sauce, honey and ginger.","Sear the salmon skin-side down for 4 minutes, flip, and cook 3 more.","Pour in the sauce and let it bubble for 1 minute, spooning it over the fish.","Slice the cucumber and scallions. Build bowls of rice, salmon and cucumber, then top with sesame and scallions."]'::jsonb),
  (4, 'cook', 'Grilled cheese and tomato soup', 'The classic rainy-night combo', 'comfy', 1, 15, 'Crispy buttered sourdough with cheddar, dunked in a quick tomato soup.', '[{"qty":"4 slices","name":"sourdough bread"},{"qty":"4 oz","name":"cheddar"},{"qty":"2 tbsp","name":"butter"},{"qty":"1 can (28 oz)","name":"crushed tomatoes"},{"qty":"1 cup","name":"vegetable broth"},{"qty":"1 tsp","name":"sugar"}]'::jsonb, '["Simmer the tomatoes, broth and sugar for 10 minutes. Season with salt and pepper.","Butter the outsides of the bread and fill with cheddar.","Cook the sandwiches in a pan over medium heat, about 3 minutes per side, until golden and melty.","Blend the soup if you like it smooth.","Cut the sandwiches into strips and dunk."]'::jsonb),
  (5, 'cook', 'Shrimp tacos with slaw', 'Crunchy, zesty, done fast', 'fresh', 2, 20, 'Garlicky shrimp, lime cabbage slaw and a spoon of chipotle mayo.', '[{"qty":"1 lb","name":"shrimp, peeled"},{"qty":"2 cups","name":"shredded cabbage"},{"qty":"2","name":"limes"},{"qty":"3 tbsp","name":"mayonnaise"},{"qty":"1 tsp","name":"chipotle in adobo"},{"qty":"2 cloves","name":"garlic"},{"qty":"8 small","name":"corn tortillas"},{"qty":"1 handful","name":"cilantro"}]'::jsonb, '["Toss the cabbage with the juice of 1 lime and a pinch of salt.","Stir the chipotle into the mayo.","Sauté the garlic and shrimp in a hot pan for 2 to 3 minutes, until pink.","Warm the tortillas.","Fill with slaw and shrimp, add a spoon of chipotle mayo, cilantro and a lime wedge."]'::jsonb),
  (6, 'cook', 'Spicy peanut noodles', 'Slurpy, nutty, a little fiery', 'spicy', 1, 15, 'Noodles tossed in peanut butter, soy, lime and chili crisp. Top with scallions.', '[{"qty":"8 oz","name":"noodles (spaghetti works)"},{"qty":"1/3 cup","name":"peanut butter"},{"qty":"3 tbsp","name":"soy sauce"},{"qty":"1","name":"lime"},{"qty":"1 tbsp","name":"chili crisp"},{"qty":"1 tsp","name":"honey"},{"qty":"3","name":"scallions"},{"qty":"2 tbsp","name":"roasted peanuts"}]'::jsonb, '["Cook the noodles. Save a little of the cooking water.","Whisk the peanut butter, soy sauce, lime juice, chili crisp and honey with a few spoons of hot water until smooth.","Toss the noodles in the sauce.","Top with sliced scallions and chopped peanuts."]'::jsonb),
  (7, 'cook', 'Greek chicken salad', 'Bright, crunchy and filling', 'fresh', 2, 25, 'Lemon-oregano chicken, cucumber, tomato, olives, feta and warm pita.', '[{"qty":"1 lb","name":"chicken thighs"},{"qty":"1","name":"lemon"},{"qty":"1 tsp","name":"dried oregano"},{"qty":"2 tbsp","name":"olive oil"},{"qty":"1","name":"cucumber"},{"qty":"1 pint","name":"cherry tomatoes"},{"qty":"1/2 cup","name":"kalamata olives"},{"qty":"4 oz","name":"feta"},{"qty":"4","name":"pita breads"}]'::jsonb, '["Toss the chicken with lemon juice, oregano, olive oil and salt. Let it sit for 5 minutes.","Cook in a hot pan for 5 to 6 minutes per side.","Chop the cucumber and halve the tomatoes.","Slice the chicken over the vegetables with olives and crumbled feta.","Warm the pita and serve on the side."]'::jsonb),
